:root {
  color-scheme: dark;

  --bg: #0b0b0f;
  --bg-elev: #131319;
  --bg-input: #0e0e14;
  --line: #26262f;
  --line-strong: #3a3a47;
  --fg: #ececf1;
  --fg-muted: #9a9aab;
  --accent: #7c5cff;
  --accent-soft: rgba(124, 92, 255, 0.16);
  --danger: #ff6b81;
  --ok: #4ade80;
  /* Mirror the win/lose event types' accent defaults (src/lib/eventTypes.ts)
     so the control dock's buttons match the animation each one triggers —
     not the general-purpose --ok/--danger tokens. */
  --dock-win-accent: #31d0aa;
  --dock-lose-accent: #ff5c8a;
  --radius: 10px;
  --font: var(--font-geist-sans), system-ui, sans-serif;
  --mono: var(--font-geist-mono), ui-monospace, SFMono-Regular, monospace;
}

* {
  box-sizing: border-box;
  padding: 0;
  margin: 0;
}

html {
  height: 100%;
}

html,
body {
  max-width: 100vw;
  /* clip, not hidden: `hidden` makes these a scroll container, which stops
     position:sticky working for the nav and the editor's save bar. */
  overflow-x: clip;
}

body {
  min-height: 100%;
  display: flex;
  flex-direction: column;
  color: var(--fg);
  font-family: var(--font);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background:
    radial-gradient(1100px 620px at 12% -12%, rgba(124, 92, 255, 0.16), transparent 60%),
    radial-gradient(900px 520px at 92% 0%, rgba(34, 211, 238, 0.08), transparent 55%),
    var(--bg);
  background-attachment: fixed;
}

h1 {
  font-size: 26px;
  letter-spacing: -0.02em;
}
h2 {
  font-size: 15px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: 600;
}

a {
  color: var(--accent);
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}

code {
  font-family: var(--mono);
  font-size: 12.5px;
  background: var(--bg-input);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 3px 6px;
  color: #cdc4ff;
}

/* ---- forms ---------------------------------------------------------- */

label {
  display: grid;
  gap: 6px;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--fg-muted);
}

input,
select,
textarea {
  width: 100%;
  font: inherit;
  font-size: 13px;
  color: var(--fg);
  background: var(--bg-input);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 10px;
  transition: border-color 0.15s, box-shadow 0.15s;
}
input::placeholder {
  color: #5c5c6b;
}
input:hover,
select:hover {
  border-color: var(--line-strong);
}
input:focus-visible,
select:focus-visible,
button:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--fg-muted) 50%),
    linear-gradient(135deg, var(--fg-muted) 50%, transparent 50%);
  background-position: calc(100% - 16px) calc(50% + 1px), calc(100% - 11px) calc(50% + 1px);
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 30px;
}
input[type='checkbox'] {
  width: 15px;
  height: 15px;
  accent-color: var(--accent);

