/* primary action: submit buttons and anything opting in */
button[type='submit'],
.btn-primary {
  display: inline-block;
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}
a.btn-primary:hover {
  text-decoration: none;
}
button[type='submit']:hover:not(:disabled),
.btn-primary:hover:not(:disabled) {
  background: #6c4cf0;
  border-color: #6c4cf0;
}

fieldset {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  background: rgba(255, 255, 255, 0.015);
}
legend {
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--fg-muted);
  padding: 0 6px;
}

/* ---- shared bits ---------------------------------------------------- */

.panel {
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 20px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.4), 0 12px 32px -18px rgba(0, 0, 0, 0.9);
}

.muted {
  color: var(--fg-muted);
  font-size: 12.5px;
}

.chip {
  font-family: var(--mono);
  font-size: 12px;
  padding: 4px 9px;
  border-radius: 999px;
  background: var(--accent-soft);
  border: 1px solid rgba(124, 92, 255, 0.35);
  color: #c3b4ff;
}
.chip:hover:not(:disabled) {
  background: rgba(124, 92, 255, 0.28);
  border-color: var(--accent);
}

/* shell + side panel */
.shell {
  display: flex;
  min-height: 100vh;
  align-items: flex-start;
}
.shell-main {
  flex: 1;
  min-width: 0;
}

